import json, os, subprocess, sys
from pathlib import Path
os.environ['HF_HOME'] = '/kaggle/temp/huggingface'
os.environ['TOKENIZERS_PARALLELISM'] = 'true'
root = Path('/kaggle/working/source'); root.mkdir(exist_ok=True)
for name, content in json.loads('{"prepare.py": "\\"\\"\\"Bounded CPU preparation, original tokenizer and document-disjoint splits.\\"\\"\\"\\nimport argparse, gzip, hashlib, json, os, random, re, time\\nfrom pathlib import Path\\nimport numpy as np\\nfrom huggingface_hub import HfApi, hf_hub_download\\nfrom tokenizers import Tokenizer, models, pre_tokenizers, decoders, trainers\\n\\nLICENSES = {\'mit\', \'apache-2.0\', \'bsd-2-clause\', \'bsd-3-clause\', \'isc\', \'unlicense\', \'cc0-1.0\'}\\nSEED = 20261003\\n\\ndef fingerprint(text):\\n    return hashlib.blake2b(re.sub(r\'\\\\s+\', \' \', text).strip().encode(), digest_size=16).digest()\\n\\ndef split_for(digest):\\n    bucket = int.from_bytes(digest[:8], \'big\') % 1000\\n    return \'validation\' if bucket < 5 else \'audit\' if bucket < 10 else \'train\'\\n\\ndef filtered(row, spec, domain):\\n    if domain == \'code\' and (row.get(\'license\', \'\').lower() not in LICENSES or row.get(\'autogenerated\', False)):\\n        return None\\n    text = row.get(spec[\'field\'], \'\')\\n    if not isinstance(text, str) or not 384 <= len(text) <= 120000:\\n        return None\\n    if domain == \'pt\' and row.get(\'language_score\', 1.0) < 0.9:\\n        return None\\n    if \'\\\\x00\' in text or \'-----BEGIN PRIVATE KEY\' in text or \'-----BEGIN RSA PRIVATE KEY\' in text:\\n        return None\\n    return text\\n\\ndef source_files(spec):\\n    paths = [f for f in HfApi().list_repo_files(spec[\'repo\'], repo_type=\'dataset\', revision=spec[\'revision\'])\\n             if f.startswith(spec[\'prefix\']) and f.endswith((\'.parquet\', \'.json.gz\'))]\\n    random.Random(SEED).shuffle(paths)\\n    if not paths:\\n        raise RuntimeError(\'No source files: \' + spec[\'repo\'])\\n    return paths\\n\\ndef rows(spec, paths):\\n    for name in paths:\\n        print(json.dumps({\'event\': \'download\', \'repo\': spec[\'repo\'], \'file\': name}), flush=True)\\n        path = hf_hub_download(spec[\'repo\'], filename=name, repo_type=\'dataset\', revision=spec[\'revision\'])\\n        if name.endswith(\'.parquet\'):\\n            import pyarrow.parquet as pq\\n            for batch in pq.ParquetFile(path).iter_batches(batch_size=256):\\n                yield from batch.to_pylist()\\n        else:\\n            with gzip.open(path, \'rt\', encoding=\'utf-8\') as handle:\\n                for line in handle:\\n                    yield json.loads(line)\\n\\ndef sha256_file(path):\\n    h = hashlib.sha256()\\n    with open(path, \'rb\') as f:\\n        while chunk := f.read(8 * 1024 * 1024):\\n            h.update(chunk)\\n    return h.hexdigest()\\n\\ndef main():\\n    args = argparse.ArgumentParser()\\n    args.add_argument(\'--out\', default=\'/kaggle/working/corpus\')\\n    args.add_argument(\'--tokens\', type=int, default=2_000_000_000)\\n    args.add_argument(\'--vocab\', type=int, default=32768)\\n    cfg = args.parse_args()\\n    root = Path(cfg.out); root.mkdir(parents=True, exist_ok=True)\\n    sources = json.loads(Path(__file__).with_name(\'sources.json\').read_text())\\n    paths = {key: source_files(spec) for key, spec in sources.items()}\\n    sample_path = root / \'tokenizer-sample.txt\'\\n    with sample_path.open(\'w\', encoding=\'utf-8\') as sample:\\n        for domain, spec in sources.items():\\n            size, target = 0, int(80_000_000 * spec[\'weight\'])\\n            for row in rows(spec, paths[domain]):\\n                text = filtered(row, spec, domain)\\n                if text is None or split_for(fingerprint(text)) != \'train\':\\n                    continue\\n                sample.write(text + \'\\\\n\'); size += len(text.encode())\\n                if size >= target:\\n                    break\\n    tok = Tokenizer(models.BPE(unk_token=\'<|unk|>\'))\\n    tok.pre_tokenizer = pre_tokenizers.ByteLevel(add_prefix_space=False)\\n    tok.decoder = decoders.ByteLevel()\\n    specials = [\'<|pad|>\', \'<|unk|>\', \'<|eos|>\', \'<|user|>\', \'<|assistant|>\', \'<|system|>\', \'<|tool|>\']\\n    trainer = trainers.BpeTrainer(vocab_size=cfg.vocab, min_frequency=3, special_tokens=specials,\\n                                 initial_alphabet=pre_tokenizers.ByteLevel.alphabet(), show_progress=True)\\n    tok.train([str(sample_path)], trainer)\\n    if tok.get_vocab_size() != cfg.vocab:\\n        raise RuntimeError(f\'Unexpected vocabulary: {tok.get_vocab_size()}\')\\n    tok.save(str(root / \'tokenizer.json\'))\\n    sample_path.unlink()\\n    eos = tok.token_to_id(\'<|eos|>\')\\n    counts, documents, hashes = {}, {}, {}\\n    seen = set()\\n    start = time.monotonic()\\n    with gzip.open(root / \'provenance.jsonl.gz\', \'wt\', encoding=\'utf-8\') as provenance:\\n        for domain, spec in sources.items():\\n            target = int(cfg.tokens * spec[\'weight\'])\\n            count = {split: 0 for split in (\'train\', \'validation\', \'audit\')}\\n            docs = {split: 0 for split in count}\\n            handles = {split: (root / f\'{domain}-{split}.bin\').open(\'wb\') for split in count}\\n            pending = []\\n            def write_pending():\\n                if not pending:\\n                    return\\n                encoded = tok.encode_batch([item[0] for item in pending], add_special_tokens=False)\\n                for (_, digest, split, row), enc in zip(pending, encoded):\\n                    limit = target if split == \'train\' else 1_000_000\\n                    if count[split] >= limit:\\n                        continue\\n                    ids = enc.ids + [eos]\\n                    ids = ids[:limit - count[split]]\\n                    np.asarray(ids, dtype=np.uint16).tofile(handles[split])\\n                    count[split] += len(ids); docs[split] += 1\\n                    provenance.write(json.dumps({\'domain\': domain, \'split\': split, \'fingerprint\': digest.hex(),\\n                                                 \'url\': row.get(\'url\'), \'repo\': row.get(\'repo_name\'),\\n                                                 \'path\': row.get(\'path\'), \'license\': row.get(\'license\', spec[\'license\'])}) + \'\\\\n\')\\n                pending.clear()\\n            try:\\n                for row in rows(spec, paths[domain]):\\n                    text = filtered(row, spec, domain)\\n                    if text is None:\\n                        continue\\n                    digest = fingerprint(text)\\n                    if digest in seen:\\n                        continue\\n                    seen.add(digest)\\n                    split = split_for(digest)\\n                    limit = target if split == \'train\' else 1_000_000\\n                    if count[split] >= limit:\\n                        continue\\n                    pending.append((text, digest, split, row))\\n                    if len(pending) >= 64:\\n                        write_pending()\\n                    if count[\'train\'] >= target and min(count[\'validation\'], count[\'audit\']) >= 200000:\\n                        break\\n                write_pending()\\n            finally:\\n                for handle in handles.values():\\n                    handle.close()\\n            if count[\'train\'] < target or min(count[\'validation\'], count[\'audit\']) < 200000:\\n                raise RuntimeError(f\'Insufficient data for {domain}: {count}\')\\n            counts[domain], documents[domain] = count, docs\\n            for split in count:\\n                hashes[f\'{domain}-{split}.bin\'] = sha256_file(root / f\'{domain}-{split}.bin\')\\n            print(json.dumps({\'event\': \'domain_ready\', \'domain\': domain, \'tokens\': count}), flush=True)\\n    hashes[\'tokenizer.json\'] = sha256_file(root / \'tokenizer.json\')\\n    manifest = {\'seed\': SEED, \'vocabulary\': tok.get_vocab_size(), \'counts\': counts, \'documents\': documents,\\n                \'sources\': sources, \'sha256\': hashes, \'preparation_seconds\': time.monotonic() - start,\\n                \'split_policy\': \'normalized exact-text hash; validation buckets 0..4, audit 5..9; tokenizer trained on train only\',\\n                \'deduplication\': \'normalized exact document text across all three corpora; no near-duplicate guarantee\'}\\n    (root / \'manifest.json\').write_text(json.dumps(manifest, indent=2))\\n    (root / \'sources.json\').write_text(json.dumps(sources, indent=2))\\n    print(json.dumps({\'event\': \'corpus_ready\', \'counts\': counts}), flush=True)\\n\\nif __name__ == \'__main__\':\\n    main()\\n", "sources.json": "{\\n  \\"pt\\": {\\n    \\"repo\\": \\"HuggingFaceFW/fineweb-2\\",\\n    \\"revision\\": \\"af9c13333eb981300149d5ca60a8e9d659b276b9\\",\\n    \\"prefix\\": \\"data/por_Latn/train/\\",\\n    \\"field\\": \\"text\\",\\n    \\"weight\\": 0.60,\\n    \\"license\\": \\"ODC-BY; underlying web content retains its original terms\\",\\n    \\"url\\": \\"https://huggingface.co/datasets/HuggingFaceFW/fineweb-2\\"\\n  },\\n  \\"en\\": {\\n    \\"repo\\": \\"HuggingFaceFW/fineweb-edu\\",\\n    \\"revision\\": \\"87f09149ef4734204d70ed1d046ddc9ca3f2b8f9\\",\\n    \\"prefix\\": \\"sample/10BT/\\",\\n    \\"field\\": \\"text\\",\\n    \\"weight\\": 0.25,\\n    \\"license\\": \\"ODC-BY; underlying web content retains its original terms\\",\\n    \\"url\\": \\"https://huggingface.co/datasets/HuggingFaceFW/fineweb-edu\\"\\n  },\\n  \\"code\\": {\\n    \\"repo\\": \\"codeparrot/codeparrot-clean\\",\\n    \\"revision\\": \\"35a59fb025bc0a102f7d96eac09d145b896d487b\\",\\n    \\"prefix\\": \\"file-\\",\\n    \\"field\\": \\"content\\",\\n    \\"weight\\": 0.15,\\n    \\"license\\": \\"Only records labelled mit, apache-2.0, bsd-2-clause, bsd-3-clause, isc, unlicense or cc0-1.0\\",\\n    \\"url\\": \\"https://huggingface.co/datasets/codeparrot/codeparrot-clean\\"\\n  }\\n}\\n"}').items(): (root/name).write_text(content)
subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', 'huggingface_hub>=0.34,<2', 'tokenizers>=0.21,<0.24', 'pyarrow>=15'], check=True)
subprocess.run([sys.executable, str(root/'prepare.py')], check=True, cwd=root)
